-- ============================================================
-- 商品评价种子数据：给在售商品批量回填评价（Cloud 微服务模式）
-- 目标库：aryn_product
-- 创建日期：2026-10-22
--
-- 背景：goods_appraise 原有 394 个在售 SPU 仅 1 条评价，C 端商详
--       评价区几乎全部为空态。本脚本按即时零售（参考小象超市/盒马）
--       的商详评价形态，结合本库实际在售商品（394 个 SPU，单租户
--       1590229800633634816）补齐评价数据，使商详评价区有真实感的展示。
--
-- 口径（与代码可见性一致，已核对 GoodsAppraiseMapper.xml）：
--   · 好评率 = goods_score>=4 占比；中评 = goods_score=3；
--     差评 = goods_score<=2；图评 = pic_urls 非空
--   · 本脚本产出约 1500 条：好评≈80%、中评≈10%、差评≈10%、
--     图评≈35%（复用商品主图 URL）、商家回复≈25%
--   · order_item_id 满足 uk_goods_appraise_active_item 唯一键
--     （同租户未删除评价订单项唯一），使用 3161 种子前缀避免与真实订单冲突
--
-- 特性：可重复执行；仅清理 3160/3161/3162 固定前缀的本脚本数据，
--       不触碰存量评价；逻辑删除字段 del_flag，禁止 DROP/TRUNCATE 存量。
--
-- 执行：mysql -u root -p aryn_product < /Users/wangqingyu/IdeaProjects/codes/ARYN/aryn-mall-java/db/cloud/152goods_appraise_seed.sql
-- ============================================================

USE `aryn_product`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 0. 幂等清理（仅 3162 前缀本脚本数据） ----------
DELETE FROM `goods_appraise` WHERE `id` LIKE '3162%' OR `order_id` LIKE '3160%';

